// Bit-exact parity test: C++ non-greedy sampling vs vectors generated by the
// REAL production ops in veystrix/sampling.py (tools/gen_sampling_vectors.py).
// Compares raw bytes, not tolerances. Includes the seeded categorical draw.
//
// Generate vectors first:
//   .venv/bin/python cpp/engine/tools/gen_sampling_vectors.py \
//       --out cpp/engine/tests/sampling_vectors
#include "../src/sampling.hpp"

#include <mlx/mlx.h>

#include <cctype>
#include <cstdint>
#include <cstdio>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

namespace mx = mlx::core;
using namespace veystrix::engine;

static std::string read_all(const std::string& path) {
  std::ifstream f(path);
  std::ostringstream ss;
  ss << f.rdbuf();
  return ss.str();
}

// First differing uint32 view index, or a.size() when equal (shape mismatch
// reported separately). Mirrors test_engine_parity.cpp's bit_equal view.
static size_t first_diff(const mx::array& a, const mx::array& b, bool& shape_ok) {
  shape_ok = (a.shape() == b.shape());
  if (!shape_ok) return 0;
  mx::array av = mx::astype(mx::reshape(a, {-1}), mx::uint32);
  mx::array bv = mx::astype(mx::reshape(b, {-1}), mx::uint32);
  mx::eval(av, bv);
  if (av.size() != bv.size()) { shape_ok = false; return 0; }
  const uint32_t* pa = av.data<uint32_t>();
  const uint32_t* pb = bv.data<uint32_t>();
  for (size_t i = 0; i < av.size(); ++i)
    if (pa[i] != pb[i]) return i;
  return av.size();
}

static bool bit_equal(const mx::array& a, const mx::array& b) {
  bool ok = true;
  return first_diff(a, b, ok) == a.size() && ok;
}

static bool find_num(const std::string& s, const std::string& key, double& out) {
  auto k = s.find("\"" + key + "\"");
  if (k == std::string::npos) return false;
  auto colon = s.find(':', k);
  if (colon == std::string::npos) return false;
  size_t i = colon + 1;
  while (i < s.size() && std::isspace(static_cast<unsigned char>(s[i]))) ++i;
  size_t j = i;
  while (j < s.size() && (std::isdigit(static_cast<unsigned char>(s[j])) ||
                          s[j] == '-' || s[j] == '+' || s[j] == '.' ||
                          s[j] == 'e' || s[j] == 'E')) ++j;
  out = std::stod(s.substr(i, j - i));
  return true;
}

static bool find_bool(const std::string& s, const std::string& key, bool& out) {
  auto k = s.find("\"" + key + "\"");
  if (k == std::string::npos) return false;
  auto v = s.find_first_of("truefals", k);
  if (v == std::string::npos) return false;
  auto colon = s.find(':', k);
  if (v < colon) return false;
  out = s.compare(v, 4, "true") == 0;
  return true;
}

static std::vector<int32_t> find_int_array(const std::string& s,
                                           const std::string& key) {
  std::vector<int32_t> out;
  auto k = s.find("\"" + key + "\"");
  if (k == std::string::npos) return out;
  auto lb = s.find('[', k);
  auto rb = s.find(']', k);
  if (lb == std::string::npos || rb == std::string::npos || rb < lb) return out;
  std::string body = s.substr(lb + 1, rb - lb - 1);
  size_t i = 0;
  while (i < body.size()) {
    while (i < body.size() && !std::isdigit(static_cast<unsigned char>(body[i])) &&
           body[i] != '-') ++i;
    if (i >= body.size()) break;
    size_t j = i;
    while (j < body.size() && (std::isdigit(static_cast<unsigned char>(body[j])) ||
                               body[j] == '-')) ++j;
    out.push_back(static_cast<int32_t>(std::stoi(body.substr(i, j - i))));
    i = j;
  }
  return out;
}

static int run_case(const std::string& root, const std::string& name) {
  std::string dir = root + "/" + name;
  auto load = [&](const char* n) { return mx::load(dir + "/" + n + ".npy"); };

  std::string meta = read_all(dir + "/meta.json");
  double temperature, top_p_v, top_k_v, min_p, penalty, seed_v;
  bool has_ids = false;
  find_num(meta, "temperature", temperature);
  find_num(meta, "top_p", top_p_v);
  find_num(meta, "top_k", top_k_v);
  find_num(meta, "min_p", min_p);
  find_num(meta, "presence_penalty", penalty);
  find_num(meta, "seed", seed_v);
  find_bool(meta, "has_ids", has_ids);
  std::vector<int32_t> seen = find_int_array(meta, "seen");

  SamplingParams s;
  s.temperature = static_cast<float>(temperature);
  s.top_p = static_cast<float>(top_p_v);
  s.top_k = static_cast<int>(top_k_v);
  s.min_p = static_cast<float>(min_p);
  s.presence_penalty = static_cast<float>(penalty);

  mx::array logits = load("logits");
  mx::array exp_masked = load("masked");
  mx::array exp_kept = load("kept");
  mx::array exp_token = load("token");

  // 1) Distribution computation (the deterministic, bit-exact core).
  Distribution dist = sampling_distribution(logits, s, seen);
  mx::eval(dist.masked);
  if (has_ids) mx::eval(dist.ids);

  bool shape_ok = true;
  size_t diff = first_diff(dist.masked, exp_masked, shape_ok);
  if (!shape_ok || diff != exp_masked.size()) {
    std::fprintf(stderr, "[%s] MASKED differs: shape_ok=%d diff=%zu size=%zu\n",
                 name.c_str(), shape_ok, diff, exp_masked.size());
    return 1;
  }
  if (has_ids) {
    diff = first_diff(dist.ids, exp_kept, shape_ok);
    if (!shape_ok || diff != exp_kept.size()) {
      std::fprintf(stderr, "[%s] KEPT ids differ: shape_ok=%d diff=%zu size=%zu\n",
                   name.c_str(), shape_ok, diff, exp_kept.size());
      return 1;
    }
  }

  // 2) Seeded final draw (categorical + top-k remap). MLX Python and C++ share
  //    the PRNG, so the same seed reproduces the token bit-for-bit.
  mx::random::seed(static_cast<uint64_t>(seed_v));
  mx::array token = sample_non_greedy(logits, s, seen);
  mx::eval(token);
  diff = first_diff(token, exp_token, shape_ok);
  if (!shape_ok || diff != exp_token.size()) {
    std::fprintf(stderr, "[%s] TOKEN differs: shape_ok=%d diff=%zu size=%zu\n",
                 name.c_str(), shape_ok, diff, exp_token.size());
    return 1;
  }

  std::printf("  [%s] OK (distribution + seeded draw bit-identical)\n", name.c_str());
  return 0;
}

int main(int argc, char** argv) {
  std::string root = argc > 1 ? argv[1] : "cpp/engine/tests/sampling_vectors";
  std::ifstream cf(root + "/cases.txt");
  if (!cf) {
    std::fprintf(stderr, "cases.txt missing; run gen_sampling_vectors.py\n");
    return 2;
  }
  std::vector<std::string> cases;
  std::string line;
  while (std::getline(cf, line))
    if (!line.empty()) cases.push_back(line);
  if (cases.empty()) {
    std::fprintf(stderr, "no cases parsed\n");
    return 2;
  }
  int failed = 0;
  for (const auto& c : cases) failed += run_case(root, c);
  if (failed) {
    std::fprintf(stderr, "%d sampling case(s) FAILED\n", failed);
    return 1;
  }
  std::printf("test_sampling OK (%zu cases bit-identical to Python)\n", cases.size());
  return 0;
}
